<?php
$uid = (int)$u['id'];
handle('topup', function () use ($uid) { $c = cents($_POST['amount'] ?? ''); $cur = ($_POST['cur'] ?? 'BDT') === 'USD' ? 'USD' : 'BDT'; if (!rate_limit("topup:$uid", 10, 600)) throw new AppError('Too many demo deposits. Wait a few minutes.'); Pay::topup($uid, $cur, $c, 'Simulated deposit (demo money)'); return 'Added ' . money(dec($c), $cur) . ' of simulated demo money.'; });
handle('freeze', function () use ($uid) { $to = (int)($_POST['freeze'] ?? 0); $w = row('SELECT * FROM wallets WHERE user_id=? AND currency=?', [$uid, $_POST['cur'] === 'USD' ? 'USD' : 'BDT']); if ($w['frozen_by'] === 'admin' && !$to) throw new AppError('This wallet was frozen by an administrator. Contact support.'); q('UPDATE wallets SET frozen=?, frozen_by=? WHERE id=?', [$to, $to ? 'user' : 'none', $w['id']]); audit($uid, $to ? 'wallet_frozen' : 'wallet_unfrozen', 'wallet', (int)$w['id']); return $to ? 'Wallet frozen. Nothing can be sent or received until you unfreeze it.' : 'Wallet unfrozen.'; });
handle('convert', function () use ($uid) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); $from = $_POST['from'] === 'USD' ? 'USD' : 'BDT'; $r = Fx::convert($uid, $from, cents($_POST['amount'] ?? ''), idem_key()); return 'Converted using the simulated demonstration rate. Reference ' . val('SELECT ref FROM transactions WHERE id=?', [$r['txn_id']]); }, url('wallet'));
echo page_head('Wallet', 'Your simulated BDT and USD balances. Demo money only.');
echo '<div class="grid g2">';
foreach (['BDT', 'USD'] as $c) { $w = Ledger::wallet($uid, $c);
  echo card($c . ' wallet', '<div class="stat">' . mbal($w['balance'], $c) . '</div><p class="hint">' . ((int)$w['frozen'] ? badge('suspended') . ' Frozen' : badge('active') . ' Active') . ' &middot; <a href="' . e(url('activity', ['tab' => 'ledger', 'cur' => $c])) . '">Why is my balance this?</a></p>' .
    '<div class="row">' . form_start('topup', 'class="inline"') . '<input type="hidden" name="cur" value="' . $c . '"><div class="row">' . field('Add demo funds', 'amount', 'text', '', 'inputmode="decimal" placeholder="1000.00" required') . '<div class="fixed field"><label>&nbsp;</label>' . btn('Add', 'secondary') . '</div></div></form></div>' .
    form_start('freeze', 'class="inline"') . '<input type="hidden" name="cur" value="' . $c . '"><input type="hidden" name="freeze" value="' . ((int)$w['frozen'] ? 0 : 1) . '">' . btn((int)$w['frozen'] ? 'Unfreeze wallet' : 'Freeze wallet', 'secondary sm') . '</form>'); }
echo '</div>';
$rate = Fx::rate(); $from = ($_GET['from'] ?? 'BDT') === 'USD' ? 'USD' : 'BDT'; $to = $from === 'BDT' ? 'USD' : 'BDT'; $amt = $_GET['amount'] ?? ''; $quote = ''; 
if ($amt !== '') { try { $c = cents($amt); $qq = Fx::quote($from, $c);
  $quote = '<dl class="kv"><dt>You convert</dt><dd>' . mny(dec($c), $from) . '</dd><dt>Rate (SIMULATED, dated ' . e($qq['as_of']) . ')</dt><dd>1 USD = ' . number_format($qq['rate'], 2) . ' BDT</dd><dt>Converted amount</dt><dd>' . mny(dec($qq['gross_c']), $to) . '</dd><dt>Conversion fee (' . e(setting('fx_spread_percent')) . '%)</dt><dd>' . mny(dec($qq['fee_c']), $to) . '</dd></dl><div class="total-row"><span>You receive</span><span>' . mny(dec($qq['net_c']), $to) . '</span></div>' .
    form_start('convert') . '<input type="hidden" name="from" value="' . $from . '"><input type="hidden" name="amount" value="' . e($amt) . '">' . pin_field() . btn('Convert') . '</form>'; } catch (AppError $e) { $quote = '<div class="alert err">' . e($e->getMessage()) . '</div>'; } }
echo card('Convert currency', '<div class="alert info">The exchange rate below is a <strong>simulated demonstration rate</strong> (' . e($rate['source']) . ', dated ' . e($rate['as_of']) . '). It is not a market rate, and USD balances here are not real foreign currency.</div><form method="get"><input type="hidden" name="p" value="wallet"><div class="row">' . select('From', 'from', ['BDT' => 'BDT to USD', 'USD' => 'USD to BDT'], $from) . field('Amount', 'amount', 'text', (string)$amt, 'inputmode="decimal" required') . '<div class="fixed field"><label>&nbsp;</label><button class="btn secondary" type="submit">Preview</button></div></div></form>' . $quote);
